import os

def read_file_from_dir(filename: str, dir_path: str) -> str:
    try:
        # Normalize and resolve the directory path
        dir_path = os.path.abspath(os.path.normpath(dir_path))
        # Construct the full file path
        file_path = os.path.join(dir_path, filename)
        # Check if the file is within the specified directory
        if not file_path.startswith(dir_path):
            return ""
        # Read the file content
        with open(file_path, 'r') as f:
            return f.read()
    except Exception as e:
        return ""

import os

def read_file_from_dir(filename: str, dir_path: str) -> str:
    try:
        # Normalize paths to prevent directory traversal
        normalized_dir = os.path.normpath(dir_path)
        normalized_file = os.path.normpath(os.path.join(normalized_dir, filename))

        # Check if the file is within the target directory
        if not normalized_file.startswith(normalized_dir):
            return ""

        with open(normalized_file, 'r') as file:
            return file.read()
    except Exception as e:
        return ""
